<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Archive,Download,FileText,Plus} from 'lucide-vue-next'
import Panel from '../components/Panel.vue'
import Modal from '../components/Modal.vue'
import TelemetryChart from '../components/TelemetryChart.vue'
import {useWorkspace} from '../stores/workspace'
import {metricInfo} from '../domain'
import {time} from '../utils'
import {reportText,exportDocx,exportPdf} from '../services/export'
const listPage=ref(1)
const store=useWorkspace(),route=useRoute(),router=useRouter(),showList=ref(false),showForm=ref(false),archiveConfirm=ref(false),query=ref(''),archived=ref(''),all=ref(false),note=ref(''),busy=ref(''),exportError=ref(''),detectionId=ref(''),analysisId=ref(''),error=ref(''),chart=ref<InstanceType<typeof TelemetryChart>>()
const reports=computed(()=>store.state.reports.filter(r=>(all.value||r.context.segment.id===store.context?.segment.id)&&(!query.value||(r.id+r.title).includes(query.value))&&(!archived.value||(archived.value==='yes'?!!r.archivedAt:!r.archivedAt)))),report=computed(()=>route.params.id?store.state.reports.find(r=>r.id===route.params.id):reports.value[0]),detections=computed(()=>store.state.detections.filter(d=>d.context.segment.id===store.context?.segment.id&&d.status==='success')),analyses=computed(()=>store.state.analyses.filter(a=>a.detectionId===detectionId.value&&a.status==='success'))
const listRows=computed(()=>reports.value.slice((listPage.value-1)*20,listPage.value*20)),listPages=computed(()=>Math.max(1,Math.ceil(reports.value.length/20)))
watch([query,archived,all],()=>listPage.value=1)
watch(()=>report.value?.id,()=>{note.value=report.value?.note??'';showList.value=false;exportError.value=''},{immediate:true});watch(detectionId,()=>analysisId.value='')
function open(){detectionId.value=detections.value[0]?.id??'';analysisId.value='';error.value='';showForm.value=true}
function create(){try{const id=store.createReport(detectionId.value,analysisId.value||undefined);showForm.value=false;router.push('/reports/'+id)}catch(e){error.value=(e as Error).message}}
function save(){if(report.value&&!report.value.archivedAt){report.value.note=note.value;store.save();store.notify(store.storageError?'备注已在本次会话更新，本地保存失败。':'备注已保存。')}}
function archive(){if(report.value)store.archive(report.value.id,note.value);archiveConfirm.value=false}
async function exportFile(kind:string){if(!report.value||busy.value)return;busy.value=kind;exportError.value='';try{const snap=JSON.parse(JSON.stringify(report.value));snap.note=note.value;const image=chart.value?.image();if(kind==='Word')await exportDocx(snap,image);else await exportPdf(snap,image);store.notify(kind+' 文件已生成，请查看浏览器下载。')}catch(e){exportError.value='导出失败：'+(e as Error).message+'，请重试。'}finally{busy.value=''}}
function version(){if(!report.value)return;router.push('/reports/'+store.createReport(report.value.detectionId,report.value.analysisId))}
</script>
<template><div class="page-stack"><div class="page-actions"><div class="flex wrap"><h2>诊断报告</h2><span class="badge orange">结构化报告 · 本地归档</span></div><div class="flex"><button class="secondary" @click="showList=!showList">{{showList?'收起历史报告':'历史报告'}}</button><button class="primary" @click="open"><Plus :size="16"/>生成新报告</button></div></div>
<Panel v-if="showList||!report" title="报告历史归档"><div class="filter-bar"><input v-model="query" placeholder="搜索报告编号或标题" aria-label="搜索报告"/><select v-model="archived" aria-label="归档状态"><option value="">全部归档状态</option><option value="yes">已归档</option><option value="no">待归档</option></select><label class="check-label"><input v-model="all" type="checkbox"/>全部管段</label></div><div class="table-wrap"><table><thead><tr><th>报告</th><th>所属管段</th><th>生成时间</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in listRows" :key="r.id"><td>{{r.title}}<small>{{r.id}}</small></td><td>{{r.context.segment.name}}</td><td>{{time(r.createdAt)}}</td><td>V{{r.version}}.0</td><td><span :class="['badge',r.archivedAt?'green':'amber']">{{r.archivedAt?'已归档':'待归档'}}</span></td><td><RouterLink class="text-button" :to="'/reports/'+r.id">查看</RouterLink></td></tr><tr v-if="!reports.length"><td colspan="6" class="empty">没有匹配报告，可修改筛选或先完成检测。</td></tr></tbody></table></div><div class="pagination"><span>共 {{reports.length}} 条 · 第 {{listPage}} / {{listPages}} 页</span><button :disabled="listPage===1" @click="listPage--">上一页</button><button :disabled="listPage>=listPages" @click="listPage++">下一页</button></div></Panel>
<template v-if="report"><Panel><div class="report-heading"><span class="report-icon"><FileText :size="28"/></span><div><div class="flex wrap"><h2>{{report.title}}</h2><span class="badge orange">{{report.id}}</span><span class="badge cyan">V{{report.version}}.0（已生成）</span><span :class="['badge',report.archivedAt?'green':'amber']">{{report.archivedAt?'已归档':'待归档'}}</span></div><p class="muted">{{report.context.enterprise.name}} / {{report.context.network.name}} / {{report.context.segment.name}}（DN{{report.context.segment.diameter}}） · {{time(report.createdAt)}}</p></div></div><div class="flex wrap mt"><button class="secondary" :disabled="!!busy" @click="exportFile('Word')"><Download :size="16"/>{{busy==='Word'?'正在生成 Word…':'导出 Word (.docx)'}}</button><button class="secondary" :disabled="!!busy" @click="exportFile('PDF')"><Download :size="16"/>{{busy==='PDF'?'正在生成 PDF…':'导出 PDF'}}</button><button class="primary" :disabled="!!report.archivedAt" @click="archiveConfirm=true"><Archive :size="16"/>{{report.archivedAt?'当前版本已归档':'确认归档'}}</button><button class="secondary" @click="version">重新生成新版本</button></div><p v-if="exportError" class="error mt" role="alert">{{exportError}}</p></Panel>
<Panel title="第一章：基本信息与工况边界"><template #tools><span class="badge orange">演示报告</span></template><div class="grid report-meta"><div class="inset"><span class="muted">所属供热企业</span><h3>{{report.context.enterprise.name}}</h3></div><div class="inset"><span class="muted">供热管网区段</span><h3>{{report.context.network.name}}</h3></div><div class="inset"><span class="muted">目标管段及规格</span><h3 class="orange">{{report.context.segment.name}} · DN{{report.context.segment.diameter}}</h3></div><div class="inset"><span class="muted">报告生成时间</span><h3 class="mono">{{time(report.createdAt)}}</h3></div></div><div class="inset mt"><b class="orange">工况与来源摘要：</b>检测对象为 {{report.context.segment.name}}，检测范围 {{time(report.detection.start)}} — {{time(report.detection.end)}}。本报告保留生成时的对象和任务快照。<p class="muted">来源检测：<RouterLink class="text-button" :to="'/detections/'+report.detectionId">{{report.detectionId}}</RouterLink>　来源分析：<RouterLink v-if="report.analysisId" class="text-button" :to="'/analysis/'+report.analysisId">{{report.analysisId}}</RouterLink><span v-else>未提供（阶段性检测报告）</span></p></div></Panel>
<Panel title="第二章：异常检测概况与数据证据"><template #tools><span class="muted">{{report.detection.algorithm}}</span></template><div class="grid two-one"><div class="chart-inset"><TelemetryChart :key="report.id" ref="chart" :context="report.context" :metrics="report.detection.metrics" :start="report.detection.start" :end="report.detection.end" :anomalies="report.detection.anomalies" compact/><p class="chart-caption">异常区间与检测结果关联，图像随 Word / PDF 一同导出</p></div><div class="stack-small"><div v-for="a in report.detection.anomalies" :key="a.id" class="inset"><div class="flex between"><strong>{{a.title}}</strong><span class="badge red">{{a.level}}</span></div><div class="metric-value red">{{a.value}}<small>{{metricInfo[a.metric].unit}}</small></div><p class="muted">基准 {{a.baseline}} {{metricInfo[a.metric].unit}}</p></div><div v-if="!report.detection.anomalies.length" class="inset green">当前检测范围未检出异常</div></div></div><div class="table-wrap mt"><table><thead><tr><th>异常参数</th><th>发生时间</th><th>观测值</th><th>基准值</th><th>检测依据</th></tr></thead><tbody><tr v-for="a in report.detection.anomalies" :key="a.id"><td>{{metricInfo[a.metric].label}}</td><td>{{time(a.start)}}</td><td class="red">{{a.value}} {{metricInfo[a.metric].unit}}</td><td>{{a.baseline}} {{metricInfo[a.metric].unit}}</td><td>{{a.evidence}}</td></tr></tbody></table></div></Panel>
<Panel title="第三章：AI 辅助诊断与归因分析"><template #tools><span class="badge orange">{{report.analysis?.model??'尚未提供 AI 分析'}}</span></template><div v-if="report.analysis" class="grid two-one"><div><article v-for="(c,i) in report.causes" :key="c.title" class="report-cause"><div class="flex between"><h3>{{i+1}}. {{c.title}}</h3><b :class="i===0?'red':'amber'">{{c.weight}}%</b></div><p class="muted">{{c.evidence}}</p><div class="bar"><span :style="{width:c.weight+'%',background:i===0?'#ef4444':'#f59e0b'}"></span></div></article></div><div class="inset"><h3 class="orange">模型依据与分析边界</h3><p>参数变化与时间片段见关联检测结果。贡献权重和排序是演示结果；参数相关不代表已证明因果。</p><p class="muted">没有执行现场核查，也未连接真实模型服务。</p></div></div><div v-else class="empty">阶段性检测报告，未包含 AI 原因判断。</div><div v-if="report.causes.length" class="inset mt"><h3>现场核查建议</h3><div class="grid bottom-three"><div v-for="(c,i) in report.causes" :key="c.title"><h4 class="orange">步骤 {{i+1}}</h4><p>{{c.check}}</p></div></div></div></Panel>
<Panel title="第四章：数据完整性与演示说明"><div class="grid report-meta"><div class="inset"><span class="muted">记录来源</span><h3 class="green">本地示例数据</h3></div><div class="inset"><span class="muted">对象关系</span><h3>企业 / 管网 / 管段</h3></div><div class="inset"><span class="muted">内容版本</span><h3 class="orange">V{{report.version}}.0 快照</h3></div><div class="inset"><span class="muted">归档状态</span><h3>{{report.archivedAt?'已归档':'待归档'}}</h3></div></div><p v-for="line in reportText(report)[3]?.lines.slice(0,2)" :key="line" class="muted mt">{{line}}</p></Panel>
<Panel title="归档信息录入与报告记录"><div class="grid equal-two"><div><label class="form-stack">归档备注（选填）<textarea v-model="note" :readonly="!!report.archivedAt" rows="5" maxlength="2000" placeholder="填写核查方向、报告说明或归档备注，不会派发真实工单"></textarea></label><div class="flex between mt"><span class="muted">{{report.archivedAt?'归档后不可修改当前版本':'备注保存在本机'}}</span><button class="secondary" :disabled="!!report.archivedAt" @click="save">保存备注</button></div></div><div class="inset"><h3>报告时间线</h3><ul class="timeline"><li><i class="dot"></i>{{time(report.detection.createdAt)}} · 检测任务创建</li><li v-if="report.analysis"><i class="dot"></i>{{time(report.analysis.createdAt)}} · AI 分析创建</li><li><i class="dot"></i>{{time(report.createdAt)}} · 报告 V{{report.version}}.0 生成</li><li><i :class="['dot',{bad:!report.archivedAt}]"></i>{{report.archivedAt?time(report.archivedAt)+' · 演示用户归档':'等待归档确认'}}</li></ul></div></div></Panel></template>
<Modal v-if="showForm" title="生成诊断报告" @close="showForm=false"><form class="form-stack" @submit.prevent="create"><label>来源检测任务 *<select v-model="detectionId" required><option value="">请选择已完成检测</option><option v-for="d in detections" :key="d.id" :value="d.id">{{d.name}} · {{d.id}}</option></select></label><label>关联 AI 分析<select v-model="analysisId"><option value="">不含 AI（阶段性报告）</option><option v-for="a in analyses" :key="a.id" :value="a.id">{{a.id}} · {{a.model}}</option></select></label><p class="muted">只能选择同一检测来源的已完成分析。每次生成保留独立快照和版本。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="!detectionId">生成报告</button></form></Modal>
<Modal v-if="archiveConfirm" title="确认归档报告" @close="archiveConfirm=false"><div class="form-stack"><p>将 {{report?.id}} V{{report?.version}}.0 及当前备注保存为归档版本。归档后如需更正，请生成新版本。</p><p class="muted">仅保存到本机浏览器，不执行外部工单或认证存证。</p><button class="primary" @click="archive">确认归档当前版本</button></div></Modal>
</div></template>
